// C implementation of vstodo cmdAdd header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_add.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_add.go.\n\n#ifndef VSTODO_C_CMD_ADD_H\n#define VSTODO_C_CMD_ADD_H\n\n// Stage file contents into the index.\n// Equivalent to Go cmdAdd function.\n// app — vstodo application context pointer\n// args — file paths to stage (relative to working tree)\n// arg_count — number of file path arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_add(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_ADD_H